oracle_greeting_function_template:
-- 挨拶文を返すストアドファンクション。
CREATE OR REPLACE FUNCTION {{schema}}.say_hello(name IN VARCHAR2) RETURN VARCHAR2
IS
  message VARCHAR2(100);
BEGIN
  message := 'hello! ' || name;
  RETURN message;
END;
/

